import{_ as t,o as a,c as s,a6 as o}from"./chunks/framework.DIp0zHSV.js";const u=JSON.parse('{"title":"Getting AI Help","description":"Get Claude, ChatGPT or another AI assistant to write LCARdS YAML that works: the LCARdS skill for Claude, what to give other assistants, and how to check the result.","frontmatter":{"description":"Get Claude, ChatGPT or another AI assistant to write LCARdS YAML that works: the LCARdS skill for Claude, what to give other assistants, and how to check the result."},"headers":[],"relativePath":"getting-started/ai-assistance.md","filePath":"getting-started/ai-assistance.md","lastUpdated":1792205873000}'),n={name:"getting-started/ai-assistance.md"};function i(l,e,r,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="getting-ai-help" tabindex="-1">Getting AI Help <a class="header-anchor" href="#getting-ai-help" aria-label="Permalink to &quot;Getting AI Help&quot;">​</a></h1><p>An AI assistant can write LCARdS cards and whole dashboards for you. It just needs to know LCARdS first.</p><ul><li>Out of the box, a chatbot has never seen LCARdS. It guesses, and guessed options are silently ignored.</li><li>Give it the real list of LCARdS options and it stops guessing.</li><li>Check what it wrote before you paste it into Home Assistant.</li></ul><h2 id="with-claude-easiest" tabindex="-1">With Claude (easiest) <a class="header-anchor" href="#with-claude-easiest" aria-label="Permalink to &quot;With Claude (easiest)&quot;">​</a></h2><p>The <strong>LCARdS skill</strong> teaches Claude everything for your LCARdS version: every option, every built-in preset and colour, the docs, the gallery dashboards and the config checker.</p><ol><li>Add the skill to Claude: <ul><li><p><strong>Claude Code:</strong> install the LCARdS plugin. In a Claude Code session, run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin marketplace add https://lcards.unimatrix01.ca/marketplace.json</span></span>
<span class="line"><span>/plugin install lcards@lcards</span></span></code></pre></div></li><li><p><strong>claude.ai or the Claude apps:</strong> download <a href="/dev/tools/lcards-skill.zip"><code>lcards-skill.zip</code></a> and upload it as a custom skill in <strong>Settings</strong> (needs code execution turned on).</p></li></ul></li><li>Ask. For example: <ul><li>&quot;Make me an LCARdS button for <code>light.kitchen</code> that turns red when it&#39;s on.&quot;</li><li>&quot;Build an engineering dashboard with my <code>sensor.power_*</code> entities.&quot;</li></ul></li></ol><p>Claude asks for your real entity ids instead of inventing them, and checks its own YAML before handing it over.</p><details class="details custom-block"><summary>Keeping the Claude Code plugin up to date</summary><p>Each LCARdS release comes with a new version of the plugin. To get it, run <code>/plugin marketplace update lcards</code>, or open <code>/plugin</code>, go to <strong>Marketplaces</strong>, select <strong>lcards</strong> and turn on <strong>Enable auto-update</strong>. Run <code>/reload-plugins</code> (or start a new session) to load the new version.</p><ul><li><strong>Running a dev build of LCARdS?</strong> Use the dev channel instead, which follows the <a href="https://lcards.unimatrix01.ca/dev/" target="_blank" rel="noreferrer">dev docs</a>: <code>/plugin marketplace add https://lcards.unimatrix01.ca/dev/marketplace.json</code>, then <code>/plugin install lcards@lcards-dev</code>. Install one channel, not both.</li><li><strong>Installed the skill by hand before?</strong> Delete <code>~/.claude/skills/lcards/</code> first, so only the plugin copy loads.</li><li><strong>Prefer a manual install?</strong> Unzip <a href="/dev/tools/lcards-skill.zip"><code>lcards-skill.zip</code></a> into <code>~/.claude/skills/</code>, so you have <code>~/.claude/skills/lcards/SKILL.md</code>. It won&#39;t update itself.</li><li>The plugin needs Claude Code 2.1.224 or newer.</li></ul></details><div class="info custom-block"><p class="custom-block-title">Other tools that support skills</p><p>The LCARdS skill follows the open <a href="https://agentskills.io" target="_blank" rel="noreferrer">Agent Skills</a> standard, so any tool that supports Agent Skills can load the same zip. We build and test it with Claude.</p></div><div class="tip custom-block"><p class="custom-block-title">Claude can check YAML too</p><p>Already have a config, from you or from another tool? Paste it into Claude with the skill loaded and ask <em>&quot;check this LCARdS config and fix it&quot;</em>. Claude runs the same checker as the <a href="./config-checker.html">Check Your Config</a> page and explains each problem.</p></div><h2 id="give-claude-your-home-s-context-ha-mcp" tabindex="-1">Give Claude your home&#39;s context (ha-mcp) <a class="header-anchor" href="#give-claude-your-home-s-context-ha-mcp" aria-label="Permalink to &quot;Give Claude your home&#39;s context (ha-mcp)&quot;">​</a></h2><p>On its own, Claude doesn&#39;t know your Home Assistant: you tell it your entity ids. The community <a href="https://github.com/homeassistant-ai/ha-mcp" target="_blank" rel="noreferrer"><strong>ha-mcp</strong></a> server connects Claude to your Home Assistant, so together with the LCARdS skill Claude can look things up for itself:</p><ul><li>your <strong>areas and floors</strong>, to group a dashboard by room;</li><li>your <strong>entities</strong> and their current <strong>states</strong>, so it uses your real entity ids;</li><li>which devices are lights, sensors, switches and so on, to pick the right card for each.</li></ul><p>Then ask, for example: <em>&quot;Build an LCARdS engineering dashboard for the devices in my garage&quot;</em> or <em>&quot;Make a bridge view with a button for every light on the ground floor.&quot;</em></p><div class="warning custom-block"><p class="custom-block-title">ha-mcp is not part of LCARdS</p><p>ha-mcp is a separate community project; we don&#39;t make, support or take responsibility for it. It can also change your Home Assistant (automations, dashboards, settings and more). If you only want Claude to read your setup, turn on its <strong>Read Only Mode</strong>, or connect with its read-only URL (append <code>/readonly</code> to the server address). Install and set it up by following <a href="https://github.com/homeassistant-ai/ha-mcp" target="_blank" rel="noreferrer">its own instructions</a>.</p></div><h2 id="with-other-assistants" tabindex="-1">With other assistants <a class="header-anchor" href="#with-other-assistants" aria-label="Permalink to &quot;With other assistants&quot;">​</a></h2><p>If your assistant supports Agent Skills, use the skill above. Otherwise:</p><ol><li><p><strong>Download the option list for your card</strong>, for example <a href="/dev/schema/cards/lcards-button.json"><code>lcards-button.json</code></a>. Every card is listed in <a href="/dev/schema/index.json"><code>schema/index.json</code></a>.</p></li><li><p><strong>Attach it</strong> to your chat and paste this first:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m writing YAML for LCARdS, a custom Home Assistant card system. The</span></span>
<span class="line"><span>attached JSON Schema lists every option. Only use options from the schema.</span></span>
<span class="line"><span>If something I ask for isn&#39;t there, tell me instead of inventing a key.</span></span>
<span class="line"><span>Theme colours need the theme: prefix, e.g. theme:colors.ui.primary.</span></span></code></pre></div></li><li><p><strong>Describe the card you want.</strong></p></li></ol><h2 id="check-what-it-wrote" tabindex="-1">Check what it wrote <a class="header-anchor" href="#check-what-it-wrote" aria-label="Permalink to &quot;Check what it wrote&quot;">​</a></h2><ul><li>Paste the YAML into <a href="./config-checker.html">Check Your Config</a>. It runs in your browser and points at each problem.</li><li>Or ask Claude with the skill to check it (see the tip above).</li><li>Prefer the command line? Download <a href="/dev/tools/lcards-validate.mjs"><code>lcards-validate.mjs</code></a> and run <code>node lcards-validate.mjs my-dashboard.yaml</code> (Node.js 20 or newer).</li></ul><h2 id="if-it-still-makes-things-up" tabindex="-1">If it still makes things up <a class="header-anchor" href="#if-it-still-makes-things-up" aria-label="Permalink to &quot;If it still makes things up&quot;">​</a></h2><ul><li>Paste the checker&#39;s output back into the chat and ask it to fix exactly those lines.</li><li>Remind it to re-read the attached schema and not to guess. Most assistants correct themselves once told.</li></ul><h2 id="details-for-power-users" tabindex="-1">Details for power users <a class="header-anchor" href="#details-for-power-users" aria-label="Permalink to &quot;Details for power users&quot;">​</a></h2><details class="details custom-block"><summary>What else you can attach</summary><p><strong>Schemas</strong></p><ul><li><strong>One card at a time (smallest):</strong> the card&#39;s file from <a href="/dev/schema/index.json"><code>schema/index.json</code></a>, plus the shared files its entry lists under <code>uses</code> (rules, animations, background animations, state colours, filters). Card files are 2 to 75 KB; attach only the shared files your request touches.</li><li><strong>Everything in one file:</strong> <a href="/dev/lcards-schema.json"><code>lcards-schema.json</code></a> holds every card, the <a href="./../cards/layout-view/">Layout View</a> and the LCARS shell strategy. It is about 460 KB, so it suits tools with large context windows.</li><li>Each GitHub release carries both (<code>lcards-schema.json</code>, <code>lcards-schema.zip</code>), plus the skill and the checker, matching that release exactly.</li></ul><p><strong>Docs pages</strong></p><ul><li><a href="./../cards/common.html">Common Properties</a> explains what the schema can&#39;t: entity references, the <code>theme:</code> prefix, <code>{{ }}</code> templates and actions.</li><li>The card&#39;s own page (for example <a href="./../cards/button/">Button</a> or <a href="./../cards/chart/">Chart</a>) has worked examples.</li><li>Tools that read <a href="/dev/llms.txt"><code>llms.txt</code></a> find everything from there. <a href="/dev/llms-full.txt"><code>llms-full.txt</code></a> is all the user docs in one file.</li></ul><p><strong>MSD</strong></p><p>The MSD schema (<code>custom:lcards-msd-card</code>) is large and deeply nested. Attach <a href="/dev/schema/cards/lcards-msd-card.json"><code>lcards-msd-card.json</code></a> with the shared files it uses, plus the <a href="./../cards/msd/quick-start.html">MSD Quick Start</a> or <a href="./../cards/msd/routing-concepts.html">Routing Concepts</a> page, and expect a few more rounds than for a single button.</p><p><strong>Longer prompt template</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m writing YAML configuration for LCARdS, a custom Home Assistant Lovelace</span></span>
<span class="line"><span>card system. I&#39;ve attached its JSON Schema (from https://lcards.unimatrix01.ca/schema/index.json)</span></span>
<span class="line"><span>and reference docs. Rules:</span></span>
<span class="line"><span>- Only use properties that appear in the schema for the card type I&#39;m using</span></span>
<span class="line"><span>  (resolve &quot;#/$defs/...&quot; refs within the file, and &quot;../shared/&lt;name&gt;.json&quot; refs</span></span>
<span class="line"><span>  against the shared files I attached).</span></span>
<span class="line"><span>- Do not invent properties. If something I ask for isn&#39;t in the schema, tell</span></span>
<span class="line"><span>  me instead of guessing at a plausible-sounding key.</span></span>
<span class="line"><span>- Colour values must match the schema&#39;s colour pattern: hex, rgb()/rgba()/</span></span>
<span class="line"><span>  hsl()/hsla(), var(--name), or a theme:path token (e.g. theme:colors.ui.primary).</span></span></code></pre></div></details>`,24)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
